<script setup lang="ts">
import axios from 'axios'
import { computed, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { renderAsync } from 'docx-preview'
import InspectionQuery from './InspectionQuery.vue'
import { allLibraryPages, doseDraftKey } from './personalDoseSupport'

const props=defineProps<{token:string;username:string;openCaseId?:number;canReview:boolean;canApprove:boolean;canGenerateReport:boolean}>()
const emit=defineEmits<{ 'open-inspection':[{id:number;modality:'CT'|'DR'|'DOSE'}] }>()
const queryVisible=ref(false), archiveRows=ref<any[]>([])
async function queryOpen(row:{id:number;modality:'CT'|'DR'|'DOSE'}){if(dirty.value){try{await ElMessageBox.confirm('当前修改未提交，草稿已保存在本机，是否切换？','切换项目')}catch{return}}queryVisible.value=false;if(row.modality==='DOSE')await open(row.id);else emit('open-inspection',row)}
async function loadReports(){archiveRows.value=form.value.id?(await api.get(`/api/personal-dose/cases/${form.value.id}/reports`)).data:[]}
const api=axios.create({baseURL:import.meta.env.VITE_API_BASE_URL || '/'})
api.interceptors.request.use(c=>{c.headers.Authorization=`Bearer ${props.token}`;return c})
type Person={dosimeterNo:string;name:string;sex:string;occupationCategory:string;job:string;startDate:string;endDate:string;wearingPosition:string;wearingDays?:number}
type Reading={sampleType:string;dosimeterNo:string;name:string;values:string[];cf:string}
type Project={id?:number;version?:number;status?:string;personnel:Person[];readings:Reading[];[key:string]:any}
const blank=():Project=>({receipt:'',unitName:'',unitAddress:'',submittingUnit:'',commissioningUnit:'',detectionCategory:'委托检测',location:'',city:'',county:'',sampleName:'个人剂量计',sampleCount:'',packaging:'剂量计盒',sampleCondition:'正常',monitoringMonths:'3',monitoringItem:'X、γ射线个人剂量当量',monitoredQuantity:'Hp(10)',cycle:'',monitoringStart:'',monitoringEnd:'',distributionStart:'',distributionEnd:'',receivedDate:'',inspectionDate:'',reportDate:'',standardBasis:'GBZ 128—2019 职业性外照射个人监测规范',detector:'',detectorType:'',instrumentDescription:'',mdl:'',investigationLevel:'',conclusion:'',personnel:[],readings:[]})
const statusNames:Record<string,string>={DRAFT:'项目创建',DATA_ENTERED:'检测录入',CALCULATED:'结果评价',PENDING_REVIEW:'待复核',REVIEWED:'待批准',APPROVED:'已批准',REPORTED:'已归档'}
const cases=ref<Project[]>([]), total=ref(0), page=ref(1), keyword=ref(''), status=ref(''), busy=ref(false)
const selected=ref<Project>(), form=ref<Project>(blank()), tab=ref('base'), wizard=ref(false), step=ref(0), dirty=ref(false), applying=ref(false)
const standards=ref<any[]>([]), devices=ref<any[]>([]), standardIds=ref<number[]>([]), deviceId=ref<number>()
const editable=computed(()=>!selected.value || ['DRAFT','DATA_ENTERED','CALCULATED'].includes(selected.value.status || 'DRAFT'))
const stage=computed(()=>({DRAFT:0,DATA_ENTERED:1,CALCULATED:2,PENDING_REVIEW:3,REVIEWED:3,APPROVED:4,REPORTED:4}[selected.value?.status || 'DRAFT'] || 0))
const draftKey=computed(()=>doseDraftKey(props.username,form.value.id))
const draftError=ref(false)
function storeDraft(notify=false){try{localStorage.setItem(draftKey.value,JSON.stringify(form.value));draftError.value=false;if(notify)ElMessage.success('草稿已保存到本机，重新登录后可继续填写')}catch{draftError.value=true;if(notify)ElMessage.error('本机存储不可用，请保持页面打开并保存项目')}}
function readDraft(){const legacy=`personal-dose-draft:${props.token.slice(-16)}:${form.value.id || 'new'}`;const saved=localStorage.getItem(draftKey.value)||sessionStorage.getItem(legacy);if(saved&&!localStorage.getItem(draftKey.value)){localStorage.setItem(draftKey.value,saved);sessionStorage.removeItem(legacy)}return saved}
watch(form,()=>{if(!applying.value && editable.value){dirty.value=true;storeDraft()}},{deep:true,flush:'sync'})
function assign(d:Project){applying.value=true;form.value=JSON.parse(JSON.stringify(d));selected.value=d.id?JSON.parse(JSON.stringify(d)):undefined;dirty.value=false;applying.value=false}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.message || e.message || '操作失败')}finally{busy.value=false}}
async function load(){const r=await api.get('/api/personal-dose/cases',{params:{keyword:keyword.value,status:status.value,page:page.value-1,size:20}});cases.value=r.data.content;total.value=r.data.totalElements}
async function open(id:number){await run(async()=>{if(dirty.value)await ElMessageBox.confirm('当前编辑未保存，是否切换项目？','未保存的内容');assign((await api.get(`/api/personal-dose/cases/${id}`)).data);tab.value='base';await loadReports();const saved=readDraft();if(saved && editable.value){const draft=JSON.parse(saved);if(draft.version===form.value.version){try{await ElMessageBox.confirm('发现本项目未提交的本地草稿，是否恢复？','恢复草稿');form.value=draft}catch{localStorage.removeItem(draftKey.value)}}}})}
async function create(){await run(async()=>{if(dirty.value)await ElMessageBox.confirm('当前编辑未保存，是否新建项目？','未保存的内容');assign(blank());tab.value="base";step.value=0;wizard.value=true;const saved=readDraft();if(saved){try{await ElMessageBox.confirm('发现未完成的新项目草稿，是否恢复？','恢复草稿');form.value=JSON.parse(saved)}catch{localStorage.removeItem(draftKey.value)}}})}
async function persist(){const key=draftKey.value;const d=(await (form.value.id?api.put(`/api/personal-dose/cases/${form.value.id}`,form.value):api.post('/api/personal-dose/cases',form.value))).data;assign(d);localStorage.removeItem(key);await load()}
async function save(){await run(async()=>{await persist();if(wizard.value)tab.value="personnel";wizard.value=false;ElMessage.success('已保存；数据修改后请重新计算')})}
function next(){if(step.value===0 && (!form.value.receipt.trim()||!form.value.unitName.trim()||!form.value.detectionCategory.trim())){ElMessage.warning('请填写受理编号、检测类别和受检单位');return}if(step.value===1&&!form.value.sampleName.trim()){ElMessage.warning('请填写样品名称');return}step.value++}
async function action(name:string){await run(async()=>{if(name==='calculate' && dirty.value)await persist();else if(dirty.value)throw new Error('请先保存修改并重新计算');let comment='';if(['submit','review','approve'].includes(name))comment=(await ElMessageBox.prompt('请输入意见（可留空）',({submit:'提交复核',review:'复核通过',approve:'批准报告'} as Record<string,string>)[name],{inputType:'textarea'})).value; if(name==='return')comment=(await ElMessageBox.prompt('请输入退回原因','退回修改',{inputValidator:v=>!!v.trim()||'退回原因不能为空'})).value;else if(['approve','archive'].includes(name))await ElMessageBox.confirm(name==='approve'?'批准后数据将冻结，修改需建立修订版。':'将按批准快照生成归档报告，下载后线下手签盖章。','确认操作');assign((await api.post(`/api/personal-dose/cases/${form.value.id}/actions/${name}`,{version:form.value.version,comment})).data);await load();await loadReports();if(name==='calculate')tab.value='evaluation';ElMessage.success('操作完成')})}
async function revision(){await run(async()=>{assign((await api.post(`/api/personal-dose/cases/${form.value.id}/revision`,{version:form.value.version})).data);tab.value='base';await load();await loadReports()})}
async function remove(){await run(async()=>{await ElMessageBox.confirm('删除此未批准项目？','删除项目');await api.delete(`/api/personal-dose/cases/${form.value.id}`,{params:{version:form.value.version}});localStorage.removeItem(draftKey.value);assign(blank());await load()})}
function addPerson(){form.value.personnel.push({dosimeterNo:'',name:'',sex:'',occupationCategory:'',job:'',startDate:form.value.monitoringStart,endDate:form.value.monitoringEnd,wearingPosition:''})}
function addReading(){form.value.readings.push({sampleType:'TEST',dosimeterNo:'',name:'',values:['','',''],cf:''})}
function match(r:Reading){if(r.sampleType==='TEST'){const p=form.value.personnel.find(p=>p.dosimeterNo===r.dosimeterNo);if(p)r.name=p.name}}
function result(no:string){return form.value.calculation?.rows?.find((r:any)=>r.dosimeterNo===no)}
function days(p:Person){if(!p.startDate||!p.endDate)return '';return Math.round((Date.parse(p.endDate)-Date.parse(p.startDate))/86400000)+1}
function importStandards(){const chosen=standards.value.filter(s=>standardIds.value.includes(s.id));if(chosen.length)form.value.standardBasis=chosen.map(s=>`${s.standardCode} ${s.standardName}`).join('；')}
function importDevice(){const d=devices.value.find(d=>d.id===deviceId.value);if(d)form.value.instrumentDescription+=(form.value.instrumentDescription?'\n':'')+`${d.deviceName}（型号：${d.deviceModel || '—'}；仪器编号：${d.deviceNo || '—'}）[证书编号：${d.certificateNo || '—'}]（有效期：${d.calibrationDate || '—'} 至 ${d.calibrationExpiry || '—'}）`}
const importKind=ref('cases'), importVisible=ref(false), importFile=ref<File>(), importResult=ref<any>(), importVersion=ref<number>()
function showImport(kind:string){if(dirty.value && kind!=='cases'){ElMessage.warning('请先保存当前修改，再导入');return}importKind.value=kind;importVisible.value=true;importFile.value=undefined;importResult.value=undefined;importVersion.value=form.value.version}
function chooseFile(e:Event){importFile.value=(e.target as HTMLInputElement).files?.[0];importResult.value=undefined}
async function upload(dryRun:boolean){await run(async()=>{if(!importFile.value)throw new Error('请选择xlsx文件');const data=new FormData();data.append('file',importFile.value);importResult.value=(await api.post(`/api/personal-dose/import/${importKind.value}`,data,{params:{dryRun,id:importKind.value==='cases'?undefined:form.value.id,version:importVersion.value}})).data;if(!dryRun){if(importResult.value.project)assign(importResult.value.project);await load();importVisible.value=false;ElMessage.success(`已导入 ${importResult.value.count} 条记录`)}})}
async function download(path:string,name:string){await run(async()=>{const r=await api.get(path,{responseType:'blob'});const u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;const disposition=r.headers['content-disposition'] as string|undefined;const encoded=disposition?.match(/filename\*=UTF-8''([^;]+)/i);a.download=encoded?decodeURIComponent(encoded[1]!):name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)})}
const previewVisible=ref(false), previewPages=ref<string[]>([]), previewHost=ref<HTMLElement>(), previewError=ref('')
async function preview(){await run(async()=>{if(dirty.value)throw new Error('请先保存后预览');previewPages.value=[];previewError.value='';previewVisible.value=true;try{previewPages.value=(await api.get(`/api/personal-dose/cases/${form.value.id}/preview-pages`)).data}catch{const r=await api.get(`/api/personal-dose/cases/${form.value.id}/report`,{params:{preview:true},responseType:'blob'});previewError.value='当前环境不支持服务器分页，以下为Word内容预览；正式分页以下载文件为准。';if(previewHost.value)await renderAsync(r.data,previewHost.value)}})}
async function library(path:string,params:Record<string,any>={}){return allLibraryPages<any>(async page=>(await api.get(path,{params:{...params,page,size:100}})).data)}
async function loadLibraries(){const results=await Promise.allSettled([library('/api/ohdp/basic/standards'),library('/api/ohdp/devices',{status:'NORMAL'})]);if(results[0].status==='fulfilled')standards.value=results[0].value;else ElMessage.warning('检测标准库加载失败，请刷新重试');if(results[1].status==='fulfilled')devices.value=results[1].value;else ElMessage.warning('检测设备库加载失败，请刷新重试')}
async function refresh(){await Promise.all([load(),loadLibraries()])}
onMounted(()=>run(async()=>{await refresh();if(props.openCaseId)await open(props.openCaseId)}))
watch(()=>props.openCaseId,id=>{if(id)void open(id)})

const fieldGroups=[[
 ['receipt','样品受理编号','text'],['detectionCategory','检测类别','text'],['unitName','受检单位','text'],['unitAddress','受检单位地址','text'],['submittingUnit','送检单位','text'],['commissioningUnit','委托单位','text'],['location','检测地点','text'],['city','所在地市','text'],['county','所在县区','text']
],[['sampleName','样品名称','text'],['monitoringMonths','监测周期（月）','text'],['cycle','第几周期','text'],['sampleCount','样品数量','text'],['packaging','样品包装','text'],['sampleCondition','样品性状','text'],['monitoringItem','监测项目','text'],['monitoredQuantity','监测量','text'],['receivedDate','收检日期','date']],
 [['distributionStart','剂量计发放开始日期','date'],['distributionEnd','剂量计发放结束日期','date'],['monitoringStart','监测开始日期','date'],['monitoringEnd','监测结束日期','date'],['inspectionDate','检测日期','date'],['reportDate','报告日期','date'],['detector','检测人','text'],['detectorType','探测器类型','text'],['mdl','最低可探测水平MDL（mSv）','text'],['investigationLevel','本周期调查水平（mSv）','text']]] as const
</script>

<template>
<div class="dose-workbench" v-loading="busy">
  <div class="dose-heading"><div><h2>个人剂量监测</h2><p>人员、剂量计与监测周期关联管理 · 按 1014 版报告输出</p></div><el-button type="primary" @click="create">新建监测项目</el-button></div>
  <div class="dose-toolbar"><el-input v-model="keyword" placeholder="受理编号 / 受检单位" clearable @keyup.enter="page=1;run(load)"/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="(label,key) in statusNames" :key="key" :label="label" :value="key"/></el-select><el-button @click="page=1;run(load)">查询</el-button><el-button @click="queryVisible=true">综合查询</el-button><el-button @click="run(refresh)">刷新</el-button><el-button @click="showImport('cases')">Excel批量新建</el-button><el-button @click="download('/api/personal-dose/import-template/cases','个人剂量项目导入模板.xlsx')">项目模板下载</el-button></div>
  <el-table :data="cases" border highlight-current-row @row-click="(r:Project)=>open(r.id!)"><el-table-column prop="receipt" label="样品受理编号" min-width="160"/><el-table-column prop="unitName" label="受检单位" min-width="200"/><el-table-column label="状态" width="125"><template #default="{row}"><el-tag>{{statusNames[row.status]}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="205"/><el-table-column width="85" label="操作"><template #default="{row}"><el-button link type="primary" @click.stop="open(row.id)">打开</el-button></template></el-table-column></el-table>
  <el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="run(load)"/>
  <el-alert v-if="draftError" title="本机草稿保存失败，请保持页面打开并及时保存项目。" type="error" :closable="false"/><el-empty v-if="!selected" description="新建或选择个人剂量监测项目"/>
  <section v-if="selected" class="dose-detail">
    <div class="dose-heading"><div><h3>{{form.receipt}} · {{form.unitName}}</h3><p>{{statusNames[selected.status || 'DRAFT']}} <span v-if="dirty">· 有未保存修改</span><span v-if="form.sourceCaseId"> · 修订自项目 {{form.sourceCaseId}}</span></p></div><el-button v-if="editable" type="primary" @click="save">保存</el-button></div>
    <el-steps :active="stage" align-center><el-step title="项目创建"/><el-step title="检测录入"/><el-step title="结果评价"/><el-step title="报告审核"/><el-step title="报告归档"/></el-steps>
    <el-alert v-if="!editable" title="当前数据已锁定。审核中可退回修改；批准后请建立修订版。" type="info" :closable="false"/>
    <el-tabs v-model="tab">
      <el-tab-pane label="基本信息" name="base"><el-form label-position="top" :disabled="!editable"><div v-for="(group,i) in fieldGroups" :key="i"><h4>{{['受检单位','样品信息','检测信息'][i]}}</h4><div class="dose-grid"><el-form-item v-for="[key,label,type] in group" :key="key" :label="label" :required="['receipt','unitName','detectionCategory','sampleName'].includes(key)"><el-date-picker v-if="type==='date'" v-model="form[key]" value-format="YYYY-MM-DD" type="date"/><el-input v-else v-model="form[key]" :maxlength="key==='unitName'?255:500"/></el-form-item></div></div><div class="dose-library"><el-select v-model="standardIds" multiple filterable placeholder="从标准库选择"><el-option v-for="s in standards" :key="s.id" :value="s.id" :label="s.standardCode+' '+s.standardName"/></el-select><el-button @click="importStandards">导入检测依据</el-button></div><el-form-item label="检测依据"><el-input v-model="form.standardBasis" type="textarea"/></el-form-item><div class="dose-library"><el-select v-model="deviceId" filterable placeholder="从检测设备库选择"><el-option v-for="d in devices" :key="d.id" :value="d.id" :label="d.deviceName+' '+(d.deviceNo||'')"/></el-select><el-button @click="importDevice">导入仪器及证书</el-button></div><el-form-item label="检测仪器及证书（可补充检定、校准证书及有效期）"><el-input v-model="form.instrumentDescription" type="textarea" :rows="3"/></el-form-item></el-form></el-tab-pane>
      <el-tab-pane label="人员信息" name="personnel"><div class="dose-toolbar"><el-button :disabled="!editable" @click="addPerson">增加人员</el-button><el-button :disabled="!editable" @click="showImport('personnel')">Excel批量导入</el-button><el-button @click="download('/api/personal-dose/import-template/personnel','个人剂量人员导入模板.xlsx')">模板下载</el-button><span>佩戴天数包含起止两日。</span></div><el-table :data="form.personnel" border><el-table-column type="index" label="序号" width="55"/><el-table-column v-for="[key,label] in [['dosimeterNo','剂量计编号'],['name','姓名'],['sex','性别'],['occupationCategory','职业类别'],['job','岗位']]" :key="key" :label="label" :min-width="key==='sex'?80:125"><template #default="{row}"><el-input v-model="row[key!]" :disabled="!editable"/></template></el-table-column><el-table-column v-for="[key,label] in [['startDate','佩戴起始日期'],['endDate','佩戴结束日期']]" :key="key" :label="label" width="155"><template #default="{row}"><el-date-picker v-model="row[key!]" type="date" value-format="YYYY-MM-DD" :disabled="!editable" style="width:135px"/></template></el-table-column><el-table-column label="天数" width="65"><template #default="{row}">{{days(row)}}</template></el-table-column><el-table-column label="佩戴位置" width="125"><template #default="{row}"><el-input v-model="row.wearingPosition" :disabled="!editable"/></template></el-table-column><el-table-column label="操作" width="70"><template #default="{$index}"><el-button link type="danger" :disabled="!editable" @click="form.personnel.splice($index,1)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="数据录入" name="readings"><div class="dose-toolbar"><el-button :disabled="!editable" @click="addReading">增加测量行</el-button><el-button :disabled="!editable" @click="showImport('readings')">Excel批量导入</el-button><el-button @click="download('/api/personal-dose/import-template/readings','个人剂量测量导入模板.xlsx')">模板下载</el-button><el-button type="primary" :disabled="!editable" @click="action('calculate')">保存并计算</el-button></div><el-alert title="待测剂量计的编号、姓名须与人员信息一致；原始值请保留末尾0等有效位数。本底采用本项目全部本底读数均值。" type="info" :closable="false"/><el-table :data="form.readings" border><el-table-column label="样品类别" width="160"><template #default="{row}"><el-select v-model="row.sampleType" :disabled="!editable" @change="match(row)"><el-option label="待测剂量计" value="TEST"/><el-option label="本底剂量计" value="BACKGROUND"/><el-option label="质控剂量计" value="QC"/></el-select></template></el-table-column><el-table-column label="剂量计编号" width="150"><template #default="{row}"><el-input v-model="row.dosimeterNo" :disabled="!editable" @change="match(row)"/></template></el-table-column><el-table-column label="姓名" width="110"><template #default="{row}"><el-input v-model="row.name" :disabled="!editable"/></template></el-table-column><el-table-column label="原始测量值（mSv）" min-width="310"><template #default="{row}"><div class="raw-values"><el-input v-for="(_,i) in row.values" :key="i" v-model="row.values[i]" :disabled="!editable" :aria-label="'原始测量值'+(Number(i)+1)"/><el-button :disabled="!editable||row.values.length<=1" @click="row.values.pop()">−</el-button><el-button :disabled="!editable||row.values.length>=50" @click="row.values.push('')">+</el-button></div></template></el-table-column><el-table-column label="刻度因子Cf" width="120"><template #default="{row}"><el-input v-model="row.cf" :disabled="!editable"/></template></el-table-column><el-table-column label="均值（mSv）" width="100"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.mean || '—'}}</template></el-table-column><el-table-column label="净计数（mSv）" width="100"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.net || '—'}}</template></el-table-column><el-table-column label="Hp(10) mSv" width="120"><template #default="{row}">{{dirty?'待重算':result(row.dosimeterNo)?.hp10 || '—'}}</template></el-table-column><el-table-column label="操作" width="65"><template #default="{$index}"><el-button link type="danger" :disabled="!editable" @click="form.readings.splice($index,1)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="结果评价" name="evaluation"><el-alert v-if="dirty || !form.calculation" title="请保存并计算，取得本次数据结果。" type="warning" :closable="false"/><template v-else><p>本底均值：{{form.calculation.backgroundMean}} · 监测人数：{{form.personnel.length}}</p><el-table :data="form.calculation.rows.filter((r:any)=>r.sampleType==='TEST')" border><el-table-column prop="dosimeterNo" label="剂量计编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="hp10" label="Hp(10)（mSv）"/><el-table-column label="提示"><template #default="{row}"><el-tag v-if="row.investigationRequired" type="danger">达到调查水平，需调查</el-tag><el-tag v-else-if="row.belowMdl" type="warning">低于MDL</el-tag><span v-else>未达到本周期调查水平</span></template></el-table-column></el-table><p class="dose-note">{{form.calculation.note}}</p></template><h4>总体结果评价</h4><el-input v-model="form.conclusion" type="textarea" :rows="5" :disabled="!editable" placeholder="请结合本周期结果填写评价；年度限值评价需全年累计监测资料，系统不会自动判为年度合格。"/><div class="dose-toolbar"><el-button :disabled="!editable" @click="save">保存评价</el-button><el-button :disabled="!editable" @click="action('calculate')">计算 / 重新计算</el-button><el-button type="primary" :disabled="selected.status!=='CALCULATED'||dirty" @click="action('submit')">提交复核</el-button></div></el-tab-pane>
      <el-tab-pane label="审核与报告" name="report"><el-alert title="本期采用线下签章：批准并生成归档报告后，下载Word手签盖章。" type="info" :closable="false"/><div class="dose-toolbar"><el-button v-if="selected.status==='PENDING_REVIEW'&&canReview" type="primary" @click="action('review')">复核通过</el-button><el-button v-if="selected.status==='REVIEWED'&&canApprove" type="primary" @click="action('approve')">批准报告</el-button><el-button v-if="(selected.status==='PENDING_REVIEW'&&canReview)||(selected.status==='REVIEWED'&&canApprove)" @click="action('return')">退回修改</el-button><el-button @click="preview">报告预览</el-button><el-button v-if="selected.status==='APPROVED'&&canGenerateReport" type="primary" @click="action('archive')">生成并归档报告</el-button><el-button v-if="selected.status==='REPORTED'&&canGenerateReport" type="primary" @click="download(`/api/personal-dose/cases/${form.id}/report`,`${form.receipt}-个人剂量检测报告.docx`)">下载正式报告</el-button><el-button v-if="['APPROVED','REPORTED'].includes(selected.status||'')" @click="revision">建立修订版</el-button><el-button v-if="editable" type="danger" plain @click="remove">删除项目</el-button></div><h4>报告归档文件（含修订版本）</h4><el-table :data="archiveRows" border><el-table-column prop="reportNo" label="报告编号" min-width="140"/><el-table-column prop="fileName" label="文件名" min-width="300"/><el-table-column prop="generatedBy" label="生成人" width="110"/><el-table-column prop="generatedAt" label="生成时间" width="200"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" :disabled="!canGenerateReport" @click="download(`/api/personal-dose/cases/${row.caseId}/report`,row.fileName)">下载</el-button></template></el-table-column></el-table><p class="dose-note">已归档报告保留原文件；需要变更时建立修订版，各版本可分别下载。</p><p v-if="form.reportSha256" class="dose-hash">归档文件SHA-256：{{form.reportSha256}}</p><el-table :data="form.history||[]" border><el-table-column prop="at" label="时间" width="225"/><el-table-column prop="actor" label="操作人" width="125"/><el-table-column label="操作" width="150"><template #default="{row}">{{({calculate:'计算',submit:'提交复核',review:'复核通过',approve:'批准',return:'退回',archive:'报告归档'} as Record<string,string>)[row.action] || row.action}}</template></el-table-column><el-table-column prop="comment" label="说明"/></el-table></el-tab-pane>
    </el-tabs>
  </section>
  <el-dialog v-model="wizard" title="新建个人剂量监测项目" width="900px" :close-on-click-modal="false"><el-steps :active="step" align-center><el-step title="受检单位"/><el-step title="样品信息"/><el-step title="检测信息"/><el-step title="确认创建"/></el-steps><p class="dose-note">编辑自动保存为本机当前账号的草稿，关闭页面或重新登录后可恢复；创建后继续录入人员和测量数据。</p><el-form label-position="top"><div v-if="step<3" class="dose-grid"><el-form-item v-for="[key,label,type] in fieldGroups[step]" :key="key" :label="label" :required="['receipt','unitName','detectionCategory','sampleName'].includes(key)"><el-date-picker v-if="type==='date'" v-model="form[key]" value-format="YYYY-MM-DD" type="date"/><el-input v-else v-model="form[key]"/></el-form-item></div><template v-if="step===2"><div class="dose-library"><el-select v-model="standardIds" multiple filterable placeholder="从标准库选择"><el-option v-for="s in standards" :key="s.id" :value="s.id" :label="s.standardCode+' '+s.standardName"/></el-select><el-button @click="importStandards">导入依据</el-button></div><el-form-item label="检测依据"><el-input v-model="form.standardBasis" type="textarea"/></el-form-item><div class="dose-library"><el-select v-model="deviceId" filterable placeholder="从设备库选择"><el-option v-for="d in devices" :key="d.id" :value="d.id" :label="d.deviceName+' '+(d.deviceNo||'')"/></el-select><el-button @click="importDevice">导入仪器证书</el-button></div><el-form-item label="仪器及证书"><el-input v-model="form.instrumentDescription" type="textarea"/></el-form-item></template><template v-if="step===3"><el-descriptions border :column="2"><el-descriptions-item v-for="[key,label] in fieldGroups.flat()" :key="key" :label="label">{{form[key] || '—'}}</el-descriptions-item><el-descriptions-item label="检测依据">{{form.standardBasis}}</el-descriptions-item><el-descriptions-item label="仪器及证书">{{form.instrumentDescription || '—'}}</el-descriptions-item></el-descriptions></template></el-form><template #footer><el-button @click="wizard=false">取消（保留草稿）</el-button><el-button @click="storeDraft(true)">保存草稿</el-button><el-button v-if="step>0" @click="step--">上一步</el-button><el-button v-if="step<3" type="primary" @click="next">下一步</el-button><el-button v-else type="primary" :loading="busy" @click="save">确认创建</el-button></template></el-dialog>
  <el-dialog v-model="queryVisible" title="综合查询（CT / DR / 个人剂量）" width="94%" destroy-on-close><InspectionQuery :token="token" @open="queryOpen"/></el-dialog>
  <el-dialog v-model="importVisible" title="Excel批量导入" width="600px"><el-alert :title="importKind==='cases'?'每行创建一个项目；先预检，再确认导入。':'导入将替换此项目对应列表；编号、姓名不匹配时整批拒绝。'" type="warning" :closable="false"/><p><input type="file" accept=".xlsx" @change="chooseFile"/></p><p v-if="importResult">预检通过，共 {{importResult.count}} 条记录。</p><template #footer><el-button @click="upload(true)" :disabled="!importFile" :loading="busy">预检</el-button><el-button type="primary" :disabled="!importResult?.dryRun" :loading="busy" @click="upload(false)">确认导入</el-button></template></el-dialog>
  <el-dialog v-model="previewVisible" title="个人剂量报告预览" width="90%" destroy-on-close><el-alert v-if="previewError" :title="previewError" type="info"/><div class="dose-preview"><img v-for="(src,i) in previewPages" :key="i" :src="src" :alt="`报告第${i+1}页`"/><div ref="previewHost"/></div></el-dialog>
</div>
</template>

